const data = msg.payload;

if (!data.nutrient || data.value === undefined || !data.zone_id) {
    msg.statusCode = 400;
    msg.payload = {error: 'Missing fields'};
    return [null, msg];
}

const nutrient = data.nutrient.toLowerCase();
msg.topic = `sensors/soil/npk/${nutrient}`;
msg.payload = {
    sensor_id: data.sensor_id,
    zone_id: data.zone_id,
    value: data.value,
    unit: data.unit,
    depth_cm: data.depth_cm,
    timestamp: data.timestamp
};

node.log(`NPK ${nutrient}: ${data.value}`);
return [msg, null];

const data = msg.payload;

if (data.value === undefined || !data.zone_id) {
    msg.statusCode = 400;
    msg.payload = {error: 'Missing fields'};
    return [null, msg];
}

msg.topic = 'sensors/soil/temperature';
msg.payload = data;

node.log(`Temperature: ${data.value}°C`);
return [msg, null];

const data = msg.payload;

if (data.level_percent === undefined) {
    msg.statusCode = 400;
    msg.payload = {error: 'Missing fields'};
    return [null, msg];
}

msg.topic = 'sensors/water/level';
msg.payload = data;

node.log(`Water: ${data.level_percent}%`);
return [msg, null];

const data = msg.payload;

if (data.humidity === undefined || !data.zone_id) {
    msg.statusCode = 400;
    msg.payload = {error: 'Missing fields'};
    return [null, msg];
}

msg.topic = 'sensors/air/humidity';
msg.payload = data;

node.log(`Humidity: ${data.humidity}%`);
return [msg, null];
